import{_ as l,o as e,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Month 2021: Performance Optimization for All Flash based on aarch64","description":"","frontmatter":{"title":"Ceph Month 2021: Performance Optimization for All Flash based on aarch64","date":"2021-06-11T00:00:00.000Z","updated":"2021-06-12T00:00:00.000Z","tags":["Ceph","Performance Optimization","All Flash Storage","aarch64","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Performance_Optimization_for_All_Flash_based_on_aarch64.md","filePath":"posts/2021/Ceph_Month_2021_-_Performance_Optimization_for_All_Flash_based_on_aarch64.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Month_2021_-_Performance_Optimization_for_All_Flash_based_on_aarch64.md"};function t(n,a,h,s,_,c){return e(),o("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-基于oculus-x46的wolfram性能优化介绍" tabindex="-1">会议主题：基于Oculus X46的Wolfram性能优化介绍 <a class="header-anchor" href="#会议主题-基于oculus-x46的wolfram性能优化介绍" aria-label="Permalink to &quot;会议主题：基于Oculus X46的Wolfram性能优化介绍&quot;">​</a></h4><h4 id="主讲人-chenzon-华为" tabindex="-1">主讲人：Chenzon（华为） <a class="header-anchor" href="#主讲人-chenzon-华为" aria-label="Permalink to &quot;主讲人：Chenzon（华为）&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>介绍与背景</strong></p><ul><li>Chenzon介绍了基于Oculus X46的Wolfram性能优化方案，重点介绍了Queen Pong 920和Common 920平台的核心配置，包括32、48和64核心，以及2.6或3 GHz的Prolink技术。</li><li>讨论了基于Cranbone芯片的技术架构，包括Tesla硬件的高质量CPU、SSD等。</li><li>在Openonline平台上进行了测试，优化了CPU使用和并发槽数量。</li></ul></li><li><p><strong>性能优化措施</strong></p><ul><li>通过中断核心绑定、MTU调整和TCP参数调整优化了网络性能。</li><li>进行了IO性能优化，包括使用34页大小和opt message clc 32c。</li><li>测试了4k和54k的优化效果，显示了显著的性能提升和延迟降低。</li></ul></li><li><p><strong>多技术部署与优化</strong></p><ul><li>讨论了多技术部署，包括DDR多通道部署和消息加载槽的优化。</li><li>强调了数据流在同一NUMA节点内的完整性，以提高数据处理效率。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>计划进一步测试和优化，包括对4k和64k页面大小的进一步测试。</li><li>考虑将优化措施自动化，以便在不同配置下自动调整性能。</li></ul></li></ol><h4 id="讨论与问题" tabindex="-1">讨论与问题： <a class="header-anchor" href="#讨论与问题" aria-label="Permalink to &quot;讨论与问题：&quot;">​</a></h4><ul><li><strong>CPU分区与线程管理</strong>：讨论了CPU分区的概念，以及是否可以自动进行线程管理以优化性能。</li><li><strong>页面大小与内存管理</strong>：讨论了页面大小对性能的影响，以及如何减少内存浪费。</li><li><strong>RocksDB与CRC校验</strong>：讨论了RocksDB的CRC校验问题，以及是否应将其包含在未来的版本中。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>将继续进行性能测试和优化，特别是在不同页面大小和配置下的测试。</li><li>考虑将某些优化措施自动化，以简化配置和管理。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>发送详细的CPU分区设置指南给相关团队。</li><li>提交页面大小优化的补丁或拉取请求。</li><li>考虑将RocksDB的CRC校验修复包含在未来的版本中。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在感谢Chenzon和Kevin的贡献后结束，准备进行下一场演讲。</li></ul>',16)])])}const m=l(r,[["render",t]]);export{u as __pageData,m as default};
